/* ============================================================
   أطياب الجاسم (React) — خطّافات Redux المختصرة
   نستخدمها في كل كومبوننت بدل useDispatch/useSelector الخام،
   ومعها خطّافات جاهزة للعملة واللغة (تُقرأ من Redux).
   ============================================================ */

import { useDispatch, useSelector } from "react-redux";
import { useMoney } from "./selectors.js";

export function useAppDispatch() {
  return useDispatch();
}

export function useAppSelector(selector) {
  return useSelector(selector);
}

/* العملة الحالية (مبلغ/صيغة/رمز) — مصدر واحد: ملف المستخدم */
export function useCurrency() {
  return useMoney();
}

/* ★ التنقّل لم يبقَ هنا: راوتر react-router-dom هو المسؤول (useNavigate ·
   useLocation · useParams مباشرة من الحزمة) — وهذا الملف لخطّافات Redux
   فقط: المضيف (dispatch/selector) والاشتقاقات. */
