import { createProductsSlice } from "./productsFactory.js";
import { ENDPOINTS, mockGetAllPerfumes } from "../api.js";

/* ============================================================
   أطياب الجاسم — شريحة العطور (عطور فقط، بلا بخور/عود)
   initialState = { list: [], status: idle, error: null } —
   ولا add ولا update: getAllPerfumes للقراءة فقط، ولا يُنفَّذ
   والقائمة ممتلئة (condition داخل المصنع).
   ============================================================ */

const base = createProductsSlice({
  sliceName: "perfumes",
  kind: "perfume",
  kindGroup: "perfume",
  kindLabelAr: "",
  kindLabelEn: "Perfume",
  searchType: "perfume",
  endpoint: ENDPOINTS.getAllPerfumes,
  mockFn: mockGetAllPerfumes
});

export const getAllPerfumes = base.getAll;
export const refreshPerfumesStock = base.refreshStock;
export const selectPerfumesList = base.selectList;
export const selectPerfumesStatus = base.selectStatus;
export const selectPerfumesError = base.selectError;
export const selectPerfumeById = base.selectById;

/* القائمة كاملة — الشريحة عطور فقط فلا ترشيح لازم */
export const selectPerfumeProducts = base.selectList;

export default base.reducer;
