/* بطاقات العطور/البخور/البحث — نفس شبكة .grid بلا صور */
import "./Skeletons.css";

function One() {
  return (
    <div className="card sk-card" aria-hidden="true">
      <div className="sk-block sk-card-media" />
      <div className="sk-card-body">
        <span className="sk-block sk-line" />
        <span className="sk-block sk-line short" />
        <span className="sk-block sk-line tiny" />
        <span className="sk-block sk-btn" />
      </div>
    </div>
  );
}

export default function CardSkeleton(props) {
  const count = Math.max(1, Math.min(12, Number(props.count) || 8));
  const items = [];
  for (let i = 0; i < count; i++) items.push(<One key={i} />);
  return (
    <div className="grid" role="status" aria-live="polite" aria-label="جارٍ تحميل المنتجات">
      {items}
    </div>
  );
}
