/* ★ FE31: منطق قرار العودة الخالص — نُقل من PaymentReturnPage.jsx إلى هنا
   ليُختبر بلا React؛ الصفحة تُعيد تصديره بنفس الأسماء (توافق v30). */
export function normStatus(v) {  const s = String(v == null ? "" : v).trim().toLowerCase();
  if (!s) return "pending";
  if (s === "unknown" || s === "unverified" || s === "verifying" || s === "ambiguous" || s === "غير معلوم" || s === "مجهول" || s === "غير مؤكد" || s === "غير مؤكدة" || s === "جار التحقق" || s === "جارٍ التحقق") return "unknown";
  if (s === "a" || s === "success" || s === "succeeded" || s === "succeed" || s === "authorised" || s === "authorized" || s === "captured" || s === "paid" || s === "settled" || s === "settle" || s === "approved" || s === "complete" || s === "completed" || s === "مدفوع" || s === "مدفوعة" || s === "ناجح" || s === "ناجحة" || s === "مقبول" || s === "مقبولة" || s === "تم الدفع") return "success";
  if (s === "fail" || s === "failed" || s === "failure" || s === "declined" || s === "cancelled" || s === "canceled" || s === "cancel" || s === "void" || s === "refunded" || s === "rejected" || s === "error" || s === "d" || s === "c") return "fail";
  return "pending";
}

/* ★ F6: قرار النتيجة الخالص — قابل للاختبار بلا React.
   العقد الفعلي: حقول الحالة (paymentStatus/orderStatus/needsRefundReview)
   تأتي في رد status (الاستعلام)، بينما detail (تفاصيل الطلب) قد لا تحمل
   needsRefundReview إطلاقاً — فتُقرأ الحالة أولاً ثم التفاصيل احتياطاً.
   لا اشتقاق من paymentMethod ولا بحث عن كلمات refund داخل نصوص أخرى.
   المدخل: detail (تفاصيل الطلب) + status (نتيجة الاستعلام).
   المخرج: { payRaw, ordRaw, revRaw, needsRefundReview, isCancelled, reviewOpen, phase, ... }
   ★ FE19-6: لا paid إلا بدليل نجاح صريح (normStatus(payRaw)==="success").
   الحالات مستقلة: "paid" | "paid-attention" | "failed" | "unknown" | "pending".
   paymentStatus منفصل عن orderStatus وعن needsRefundReview. */
export function resolvePaymentOutcome(detail, status) {
  const dd = detail || {};
  const st = status || {};
  function pickStrFirst(objA, objB, keys, fb) {
    let i = 0;
    for (i = 0; i < keys.length; i++) {
      const v = objA && objA[keys[i]];
      if (v != null && String(v).trim() !== "") return String(v);
    }
    for (i = 0; i < keys.length; i++) {
      const v = objB && objB[keys[i]];
      if (v != null && String(v).trim() !== "") return String(v);
    }
    return fb || "";
  }
  function pickBoolEither(objA, objB, keys) {
    let i = 0;
    for (i = 0; i < keys.length; i++) {
      const v = objA && objA[keys[i]];
      if (v === true || v === 1) return true;
      if (typeof v === "string" && v.trim().toLowerCase() === "true") return true;
    }
    for (i = 0; i < keys.length; i++) {
      const v = objB && objB[keys[i]];
      if (v === true || v === 1) return true;
      if (typeof v === "string" && v.trim().toLowerCase() === "true") return true;
    }
    return false;
  }
  /* ★ FE17-F03: فصل مصادر الحالتين — status العام للمحاولة لا يجوز
     أن يحجب orderStatus الصريح للتفاصيل. حالة الطلب من حقول الطلب
     الصريحة فقط (orderStatus/statusName بكلا الحالتين)؛ وملاذ أخير
     status العام في التفاصيل وحدها (تفاصيل قديمة بشكل {status}).
     لا paid مستنتجة عند غياب دليل الدفع (الافتراضي "" لا "paid"). */
  const payRaw = pickStrFirst(st, dd, ["paymentStatus", "PaymentStatus", "payment_status"], "")
    || pickStrFirst(st, dd, ["status", "Status", "result", "Result", "state", "State"], "");
  const ordRaw = pickStrFirst(st, dd, ["orderStatus", "OrderStatus", "order_status", "statusName", "StatusName"], "")
    || pickStrFirst(dd, {}, ["status", "Status"], "");
  const revRaw = pickStrFirst(st, dd, ["reviewStatus", "ReviewStatus", "refundStatus", "RefundStatus", "refund_status", "review_status"], "");
  const needsRefundReview = pickBoolEither(st, dd, ["needsRefundReview", "NeedsRefundReview", "needsReview", "NeedsReview"]);
  const ordNorm = String(ordRaw || "").trim().toLowerCase();
  const isCancelled = (function () {
    const cands = ["cancelled", "canceled", "cancel", "void", "voided", "refunded", "refund", "ملغي", "ملغى", "ملغاة", "مسترد", "استرداد"];
    for (let i = 0; i < cands.length; i++) {
      if (ordNorm === cands[i]) return true;
    }
    if (ordNorm.indexOf("cancel") !== -1 || ordNorm.indexOf("void") !== -1) return true;
    return false;
  })();
  const reviewOpen = !!(needsRefundReview || (function () {
    const r = String(revRaw || "").trim().toLowerCase();
    return r === "open" || r === "pending" || r === "under review" || r === "needs review" || r === "مفتوحة" || r === "قيد المراجعة" || r === "يحتاج مراجعة";
  })());
  /* ★ FE30 (عقد v36 §2): حقول السياسة من رد الحالة أولاً — reason المنظم +
     booleans مستقلة (unavailable/awaitingSettlement/resumable/resumeTranRef) +
     العدّادات. لا تُقرأ من النص العربي، ولا يُستنتج unavailable/awaiting من
     نص paymentStatus (قد لا تكونا نصاً أصلاً). التفاصيل احتياط لحقيقة الطلب. */
  const reasonV36 = (function () {
    const r = st.reason != null ? st.reason : st.Reason;
    if (r != null && String(r).trim() !== "") {
      const n = String(r).trim().toLowerCase();
      const vocab = ["ready_to_start", "retry_available", "retry_too_soon", "awaiting_settlement", "already_paid", "order_cancelled", "order_expired", "order_not_payable", "max_attempts_reached", "refund_review_open", "payment_status_unknown"];
      if (vocab.indexOf(n) !== -1) return n;
    }
    return "";
  })();
  const resumableV36 = st.resumable === true || st.Resumable === true || String(st.resumable || "").toLowerCase() === "true";
  const resumeTranRefV36 = (function () {
    const v = st.resumeTranRef != null ? st.resumeTranRef : (st.ResumeTranRef != null ? st.ResumeTranRef : st.resume_tran_ref);
    return v != null && String(v).trim() !== "" ? String(v) : "";
  })();
  function pickNum(objA, objB, keys) {
    const lists = [objA, objB];
    for (let i = 0; i < lists.length; i++) {
      const o = lists[i] || {};
      for (let j = 0; j < keys.length; j++) {
        const v = o[keys[j]];
        if (v != null && v !== "" && !isNaN(Number(v))) return Number(v);
      }
    }
    return null;
  }
  const canRetryRaw = [st, dd].some(function (o) {
    if (!o) return false;
    const v = o.canRetry != null ? o.canRetry : o.CanRetry;
    return v === true || v === 1 || String(v || "").toLowerCase() === "true";
  });
  const retryAfter = pickNum(st, dd, ["retryAfterSeconds", "RetryAfterSeconds", "retryAfter", "RetryAfter"]);
  const attemptId = pickStrFirst(st, dd, ["attemptId", "AttemptId", "attempt_id"], "");
  /* ★ FE19-6: دليل النجاح الصريح شرط أي paid — بدونه الحالات مستقلة
     (unknown/pending/failed) ولا يظهر نجاح ولا يُطلق Start تلقائي. */
  const payState = normStatus(payRaw);
  const phase = payState !== "success"
    ? (payState === "fail" ? "failed" : (payState === "unknown" ? "unknown" : "pending"))
    : ((isCancelled || reviewOpen) ? "paid-attention" : "paid");
  /* ★ FE29: عدّادات العقد (attemptsUsed/maxAttempts — مسار الحالة أولاً) +
     انتهاء الرابط للعرض + حالتا البوابة التحفظيتان (عقد FE29 §2).
     failedAttempts يُفضَّل فيه عدّ العقد على العدّ القديم. */
  const usedAttempts = pickNum(st, dd, ["attemptsUsed", "AttemptsUsed", "attempts_used", "attemptsused"]);
  const maxAttempts = pickNum(st, dd, ["maxAttempts", "MaxAttempts", "max_attempts", "maxattempts"]);
  const failedAttempts = usedAttempts != null ? usedAttempts
    : pickNum(st, dd, ["failedAttemptCount", "FailedAttemptCount", "failedAttempts", "FailedAttempts", "attemptCount", "AttemptCount"]);
  const expiresAtUtc = pickStrFirst(st, dd, ["expiresAtUtc", "ExpiresAtUtc", "expires_at_utc", "expiresAt", "ExpiresAt"], "");
  const pageUrl = pickStrFirst(st, dd, ["paymentUrl", "payment_url", "pageUrl", "page_url"], "");
  /* ★ FE30 (عقد v36 §2): unavailable/awaitingSettlement حقولا Boolean مستقلان
     (مسار الحالة أولاً) — ليستا بالضرورة نصاً داخل paymentStatus. reason
     المنظم يغلِب عند التعارض. الإرث النصي احتياط أخير فقط. */
  const unavailableBool = st.unavailable === true || st.Unavailable === true
    || String(st.unavailable != null ? st.unavailable : "").toLowerCase() === "true"
    || reasonV36 === "payment_status_unknown";
  const awaitingBool = st.awaitingSettlement === true || st.AwaitingSettlement === true
    || String(st.awaitingSettlement != null ? st.awaitingSettlement : "").toLowerCase() === "true"
    || reasonV36 === "awaiting_settlement";
  const awaitingSettlement = payState !== "success" && (awaitingBool || (function () {
    const p = String(payRaw || "").trim().toLowerCase().replace(/[-_]/g, "");
    return p === "awaitingsettlement";
  })());
  const unavailablePay = unavailableBool || (function () {
    const p = String(payRaw || "").trim().toLowerCase();
    return p === "unavailable";
  })();
  return { payRaw: payRaw, ordRaw: ordRaw, revRaw: revRaw, needsRefundReview: needsRefundReview, isCancelled: isCancelled, reviewOpen: reviewOpen, phase: phase, failedAttempts: failedAttempts, canRetry: canRetryRaw, retryAfterSeconds: retryAfter, attemptId: attemptId, attemptsUsed: usedAttempts, maxAttempts: maxAttempts, expiresAtUtc: expiresAtUtc, pageUrl: pageUrl, awaitingSettlement: awaitingSettlement, unavailablePay: unavailablePay, reason: reasonV36, resumable: resumableV36, resumeTranRef: resumeTranRefV36 };
}
/* ★ FE17-F04: بوابة إعادة الدفع الصريحة — خالصة وقابلة للاختبار بلا React.
   المدخل: fresh (رد الاستعلام الحديث قبل أي Start) + nowMs للحقن +
   waitUntilMs (نهاية انتظار retryAfter المحفوظة عند عرض الرفض، أو null).
   المخرج: { allowed, reason, waitUntilMs? } — reason:
     "cancelled" (ملغى — لا Start) · "already-paid" (مدفوع — فاتورة لا Start) ·
     "review" (مراجعة مالية — لا Start) · "not-payable" (غير قابل — لا Start) ·
     "resume" (صفحة قائمة — استرجاع بميزانية باقية ونافذة سارية فقط، FE32) ·
     "expired" (نافذة منتهية بلا صفحة — لا Start) · "exhausted" (مستنفد — لا Start) ·
     "verify" (معلق/مجهول — شاشة تحقق لا محاولة) · "forbidden"
     (canRetry=false صريح بلا استئناف) · "missing-permission" (بلا إذن صريح —
     لا افتراض من العدّ وحده) · "waiting" (انتظار نشط) · "ok" (إعادة بإذن).
   القواعد (عقد v36 §2): لا Start إلا بإذن صريح (canRetry/reason) أو استرجاع
   مصرّح، وبعد انتهاء الانتظار؛ العد التنازلي للعرض فقط والخادم يفرض القرار.
   attemptsUsed < max وحده ليس إذناً. الحقول المطلوبة: reason + canRetry/
   retryAfterSeconds/attemptsUsed/maxAttempts/resumable/resumeTranRef +
   booleans (unavailable/awaitingSettlement) + attemptId.
   ★ FE23-F3: الدفع الأول له مساره الصحيح ولا يُعامل كإعادة رفض؛ Unknown
   أو نتيجة غير متاحة = انتظار تحقق (لا طلب/صفحة دفع جديدة)؛ بعد انتهاء
   العد يُعاد الاستعلام (المؤقت لا يمنح إذناً وحده — retrySameOrder
   يستعلم أولاً)؛ 503/خطأ الاستعلام يُبقي الطلب وإسناده مع إتاحة إعادة
   الاستعلام (بلا إعلان نجاح/فشل نهائي). */
/* ★ FE17-T18: مصدّرة للاختبار */
export function retryGate(fresh, nowMs, waitUntilMs) {
  const now = nowMs != null ? Number(nowMs) : Date.now();
  const st = fresh || {};
  let oc = null;
  try { oc = resolvePaymentOutcome({}, st); } catch (e) { oc = null; }
  /* ★ FE30 (عقد v36 §2): reason المنظم أولاً، ثم الأدلة الصريحة.
     ★ FE32: المنتهي/المستنفد (سبب أو عدّادات مستنفد) يسبقان الاستئناف — لا
     استرجاع رابط قديم بعد الرفض الثاني أو انتهاء النافذة. لا يتجاوز الإلغاء أو
     الدفع المكتمل أو المراجعة المالية. attemptsUsed<max وحده ليس إذناً. */
  const reason = (oc && oc.reason) || "";
  if (oc && oc.isCancelled) return { allowed: false, reason: "cancelled" };
  if (reason === "order_cancelled") return { allowed: false, reason: "cancelled" };
  if (oc && (oc.phase === "paid" || oc.phase === "paid-attention")) return { allowed: false, reason: "already-paid" };
  if (reason === "already_paid") return { allowed: false, reason: "already-paid" };
  if (!!(oc && oc.reviewOpen) || reason === "refund_review_open") return { allowed: false, reason: "review" };
  if (reason === "order_not_payable") return { allowed: false, reason: "not-payable" };
  /* ★ FE31 (دفاعي — عقد v36 §2): تعذر قراءة الحالة يمنع أي إجراء أو استئناف —
     قبل فرع resumable. المتناقض (unavailable/resumable) = تحقق لا استرجاع. */
  if (reason === "payment_status_unknown" || !!(oc && oc.unavailablePay)) {
    return { allowed: false, reason: "verify" };
  }
  /* الاستئناف المصرح: بعد المنع النهائي/المراجعة والمنتهي/المستنفد (FE32)، وقبل بوابات الإذن */
  if (reason === "order_expired") return { allowed: false, reason: "expired" };
  if (reason === "max_attempts_reached") return { allowed: false, reason: "exhausted" };
  if (oc && oc.attemptsUsed != null && oc.maxAttempts != null && Number(oc.attemptsUsed) >= Number(oc.maxAttempts)) {
    return { allowed: false, reason: "exhausted" };
  }
  if (!!(oc && oc.resumable) && oc.resumeTranRef) return { allowed: true, reason: "resume", resumeTranRef: oc.resumeTranRef };
  if (reason === "awaiting_settlement") return { allowed: false, reason: "verify" };
  /* (نُقل فحص تعذر القراءة إلى ما قبل الاستئناف — FE31) */
  if (!!(oc && oc.awaitingSettlement)) return { allowed: false, reason: "verify" };
  /* ★ FE23-F3: دليل صريح من حقول الدفع يغلِب الحالة العامة — نجاح صريح
     (paid/paid-attention) يمنع الإعادة (فاتورة لا Start)، وUnknown صريح
     يمنع التحصيل الجديد (تحقق لا خصم). الغائب/الفارغ ليس دليلاً. */
  if (oc && oc.phase === "unknown") return { allowed: false, reason: "verify" };
  if (reason === "retry_too_soon") {
    const w0 = oc && oc.retryAfterSeconds != null ? Number(oc.retryAfterSeconds) : 0;
    return { allowed: false, reason: "waiting", waitUntilMs: now + Math.round(w0 > 0 ? w0 : 0) * 1000 };
  }
  if (reason === "retry_available") {
    const w1 = oc && oc.retryAfterSeconds != null ? Number(oc.retryAfterSeconds) : 0;
    if (w1 > 0) return { allowed: false, reason: "waiting", waitUntilMs: now + Math.round(w1) * 1000 };
    return { allowed: true, reason: "ok" };
  }
  if (reason === "ready_to_start") return { allowed: false, reason: "verify" };
  const raw = st.status != null && String(st.status) !== "" ? st.status
    : st.Status != null && String(st.Status) !== "" ? st.Status
    : st.state != null && String(st.state) !== "" ? st.state
    : st.result != null && String(st.result) !== "" ? st.result
    : st.paymentStatus != null && String(st.paymentStatus) !== "" ? st.paymentStatus
    : st.PaymentStatus != null ? st.PaymentStatus : "";
  const s = normStatus(raw);
  if (s === "success") return { allowed: false, reason: "already-paid" };
  if (s !== "fail") return { allowed: false, reason: "verify" };
  /* رفض نهائي — الإذن الصريح شرط (لا افتراض عند الغياب ولا من العدّ وحده).
     ★ FE30: attemptsUsed<max وحده ليس إذناً — canRetry الصريح (أو reason)
     وحده يمنح الإذن؛ canRetry=false الصريح = منع. */
  const used = oc && oc.attemptsUsed != null ? Number(oc.attemptsUsed) : null;
  const max = oc && oc.maxAttempts != null ? Number(oc.maxAttempts) : null;
  if (used != null && max != null && used >= max) return { allowed: false, reason: "exhausted" };
  const hasCanRetry = (st.canRetry !== undefined && st.canRetry !== null)
    || (st.CanRetry !== undefined && st.CanRetry !== null);
  const canRetry = !!(oc && oc.canRetry);
  if (canRetry) {
    const freshWait = oc && oc.retryAfterSeconds != null ? Number(oc.retryAfterSeconds) : null;
    if (freshWait != null && freshWait > 0) return { allowed: false, reason: "waiting", waitUntilMs: now + Math.round(freshWait) * 1000 };
    if (waitUntilMs != null && Number(waitUntilMs) > now) return { allowed: false, reason: "waiting", waitUntilMs: Number(waitUntilMs) };
    return { allowed: true, reason: "ok" };
  }
  if (hasCanRetry) return { allowed: false, reason: "forbidden" };
  return { allowed: false, reason: "missing-permission" };
}
