import React from "react";
import { createRoot } from "react-dom/client";
import { Provider } from "react-redux";

import store from "./redux/store";
import App from "./App";

/* ============================================================
   أطياب الجاسم (React) — نقطة الدخول (index.jsx)

   ★ الطلب: ملف CSS واحد شامل اسمه Main.css يُستدعى هنا، فيكون
     مظلّة واحدة لكل الكومبوننتس والصفحات (لا CSS داخل الكومبوننتس).
   ★ مصدر الحقيقة الوحيد للحالة هو Redux: الـ<Provider> هنا يغلّف
     الشجرة كلها، ولا يمرّر App أي حالة عبر props من الخارج.
   ============================================================ */

import "./Main.css";

const rootEl = document.getElementById("root");

createRoot(rootEl).render(
  <Provider store={store}>
    <App />
  </Provider>
);
