export function cityAr(en) {
  const s = String(en == null ? "" : en);
  return CITY_AR[s] || s;
}

const EN_BY_AR = {};
Object.keys(CITY_AR).forEach(function (en) {
  const ar = CITY_AR[en];
  if (EN_BY_AR[ar] == null) EN_BY_AR[ar] = en;
});

export function cityEn(ar) {
  const s = String(ar == null ? "" : ar);
  return EN_BY_AR[s] || null;
}
