/* ============================================================
   أطياب الجاسم (React) — شريحة معلومات المتجر (storeInfoSlice)

   بيانات «طرق الدفع» و«شركات الشحن» تُجلب من الخادم لا من ملف ثابت:
     GET  <API_BASE_URL>/api/payment-methods
     GET  <API_BASE_URL>/api/shipping-carriers

   لكل قسم حالة صريحة:
     idle      لم يُطلب بعد
     loading   جارٍ الجلب (الصفحة تُظهر مؤشّر تحميل)
     succeeded وصلت البيانات (قد تكون قائمة فارغة)
     failed    فشل الجلب (الصفحة تُظهر المحتوى الاحتياطي)

   ★ بلا أي احتياط مضمّن: ما يصل من الخادم هو ما يُعرض — أثناء
     الجلب سكيلتون، وعند الفراغ رسالة نصية.
   ============================================================ */

import { createSlice } from "@reduxjs/toolkit";
import { api, apiUrl, ENDPOINTS, atyabLog } from "../api.js";
import { kindOf, PAY_CARDS } from "../../constants/payment.js";

/* مسارات الخادم — في مكان واحد، فإضافة قسم جديد سطر واحد هنا */
export const STORE_SOURCES = {
  payments: "/api/payment-methods",
  shipping: "/api/shipping-carriers"
};

function emptySection() {
  return { items: [], status: "idle", error: "" };
}

const slice = createSlice({
  name: "storeInfo",
  initialState: {
    payments: emptySection(),
    shipping: emptySection()
  },
  reducers: {
    loadStarted: function (state, action) {
      const key = action.payload;
      if (!state[key]) state[key] = emptySection();
      state[key].status = "loading";
      state[key].error = "";
    },
    loadSucceeded: function (state, action) {
      const payload = action.payload || {};
      const key = payload.key;
      if (!state[key]) state[key] = emptySection();
      state[key].items = Array.isArray(payload.items) ? payload.items : [];
      state[key].status = "succeeded";
      state[key].error = "";
    },
    loadFailed: function (state, action) {
      const payload = action.payload || {};
      const key = payload.key;
      if (!state[key]) state[key] = emptySection();
      state[key].status = "failed";
      state[key].error = payload.error || "";
    },
    sectionReset: function (state, action) {
      const key = action.payload;
      if (state[key]) state[key] = emptySection();
    }
  }
});

export const storeInfoActions = slice.actions;
export const storeInfoReducer = slice.reducer;

/* يجلب قسماً واحداً إن لم يكن قد وصل بالفعل. تُستدعى من الصفحة عند
   التركيب: dispatch(loadStoreSection("payments")). */
const AR_NAME = {
  visa: "فيزا", mastercard: "ماستركارد", applepay: "Apple Pay",
  tamara: "تمارا", tabby: "تابي", cod: "الدفع عند الاستلام",
  mada: "مدى", stcpay: "STC Pay", transfer: "تحويل بنكي"
};

const KIND_LABEL = {
  card: { ar: "بطاقة", en: "Card" },
  wallet: { ar: "محفظة", en: "Wallet" },
  transfer: { ar: "حوالة", en: "Transfer" },
  cod: { ar: "نقداً", en: "Cash" }
};

/* مفتاح داخلي موحّد من اسم السيرفر */
export function paymentKeyOf(name, isCod) {
  if (isCod) return "cod";
  const n = String(name || "").toLowerCase().replace(/[^a-z]/g, "");
  if (n.indexOf("cash") !== -1 || n.indexOf("delivery") !== -1) return "cod";
  if (n.indexOf("apple") !== -1) return "applepay";
  if (n.indexOf("master") !== -1) return "mastercard";
  if (n.indexOf("tamara") !== -1) return "tamara";
  if (n.indexOf("tabby") !== -1) return "tabby";
  if (n.indexOf("mada") !== -1) return "mada";
  if (n.indexOf("stc") !== -1) return "stcpay";
  if (n.indexOf("transfer") !== -1 || n.indexOf("bank") !== -1) return "transfer";
  if (n.indexOf("visa") !== -1) return "visa";
  return n || "unknown";
}

/* نص الرسوم للعرض: { ar, en } — «بلا رسوم إضافية» أو «رسوم: 5» / «رسوم: 2.5%» */
export function feeText(r) {
  const fee = Number(r.fee) || 0;
  if (!fee) return { ar: "بلا رسوم إضافية", en: "No extra fees" };
  const t = String(r.feeType || "").toLowerCase().indexOf("percent") !== -1 ? fee + "%" : fee;
  return { ar: "رسوم: " + t, en: "Fee: " + t };
}

/* تطبيع عنصر السيرفر إلى شكل بطاقة PaymentMethod.
   ★ الخادم يحدّد الموجود (والرسوم تُحفظ للفاتورة لاحقاً ولا تُعرض للمستخدم)،
     وكتالوج PAY_CARDS يحدّد العنوان والشرح والشعار.
   ★ القاعدة (§6): إلكترونية = providerName != null،
     نقداً = providerName == null (مع isCashOnDelivery). */
export function normalizePayment(r) {
  const cod = r ? (r.providerName != null ? false : !!r.isCashOnDelivery) : false;
  const key = paymentKeyOf(r && r.name, cod);
  const card = PAY_CARDS[key] || null;
  const formKind = kindOf(key) || (cod ? "cod" : "card");
  return {
    id: Number((r && r.paymentMethodId) || 0),
    key: key,
    name: (card && card.title.ar) || AR_NAME[key] || String((r && r.name) || ""),
    en: (card && card.title.en) || String((r && r.name) || ""),
    mark: (card && card.mark) || key,
    tone: (card && card.tone) || (key === "cod" ? "cash" : "plain"),
    kind: (card && card.tag) || KIND_LABEL[formKind] || null,
    desc: (card && card.desc) || { ar: "ادفع بأمان عبر " + String((r && r.name) || ""), en: "Pay securely with " + String((r && r.name) || "") },
    where: r && r.providerName ? { ar: "عبر " + r.providerName, en: "via " + r.providerName } : null,
    cod: cod,
    fee: Number((r && r.fee) || 0),
    feeType: (r && r.feeType) || ""
  };
}

/* مبلغ رسوم طريقة الدفع المختارة بالمخزَّن (درهم):
   ثابتة كما هي، والنسبة على إجمالي السلة المعروض (تقدير للمعاينة —
   الفاتورة الحقيقية من الخادم). 0 بلا رسوم. */
export function paymentFeeOf(m, baseTotal) {
  const fee = Number(m && m.fee) || 0;
  if (!fee) return 0;
  const t = String((m && m.feeType) || "").toLowerCase();
  if (t.indexOf("percent") !== -1) return Math.max(0, Math.round(((Number(baseTotal) || 0) * fee) / 100));
  return Math.max(0, fee);
}

/* تطبيع شركة الشحن إلى شكل البطاقة: الاسم + السعر + الهاتف + البريد
   ★ عقد التوصيل: طريقتان مدفوعتان فقط (عادي 20 / سريع 45) — الاسم
     المعروض حرفياً في name (بلا en وبلا بيانات شركة). الشحن المجاني
     مخفي من العرض ويصفّره الخادم تلقائياً عند الاستحقاق فقط. */
export function normalizeCarrier(r) {
  const phone = String((r && r.phoneNumber) || "").trim();
  const email = String((r && r.email) || "").trim();
  /* ★ بدائل الحقول لئلا ينكسر العرض: العقد الحالي deliveryPrice +
     deliveryMethodId + name — والبدائل احتياط فقط. */
  const rawPrice = r ? (r.deliveryPrice != null ? r.deliveryPrice : (r.price != null ? r.price : (r.fee != null ? r.fee : r.cost))) : null;
  return {
    kind: "carrier",
    id: Number((r && (r.deliveryMethodId != null ? r.deliveryMethodId : r.id)) || 0),
    name: String((r && (r.name != null ? r.name : r.en)) || "").trim(),
    price: rawPrice != null && rawPrice !== "" && !isNaN(Number(rawPrice)) ? Number(rawPrice) : null,
    phone: phone,
    phoneHref: phone ? "tel:" + phone.replace(/[^+\d]/g, "") : "",
    email: email
  };
}

/* ★ عرض المدفوع فقط: أي خيار مجاني/صفري يُستبعد من القائمة حتى لا
   يُعرض ولا يُرسل id مجاني/مزور أبداً (الخادم يرفضه بـ 400 ويصفّر
   الشحن تلقائياً فقط عند الاستحقاق الحقيقي). */
export function isPaidDeliveryOption(c) {
  if (!c) return false;
  if (!(Number(c.price) > 0)) return false;
  if (/مجاني|مجاناً|free/i.test(String(c.name || ""))) return false;
  return Number(c.id) > 0;
}

export function loadStoreSection(key) {
  const path = STORE_SOURCES[key];
  return async function (dispatch, getState) {
    const current = getState().storeInfo[key];
    if (!path) return;
    if (current && (current.status === "loading" || current.status === "succeeded")) { atyabLog("storeInfo CACHE-HIT", key); return; }
    atyabLog("storeInfo FETCH", key);
    dispatch(storeInfoActions.loadStarted(key));
    try {
      if (key === "payments") {
        const res = await api.get(apiUrl(ENDPOINTS.paymentMethods));
        const list = Array.isArray(res.data) ? res.data : [];
        atyabLog("storeInfo CACHED", key, list.length);
        dispatch(storeInfoActions.loadSucceeded({ key: key, items: list.map(normalizePayment) }));
      } else {
        const res = await api.get(apiUrl(ENDPOINTS.shippingCarriers));
        const list = Array.isArray(res.data) ? res.data : [];
        atyabLog("storeInfo CACHED", key, list.length);
        dispatch(storeInfoActions.loadSucceeded({ key: key, items: list.map(normalizeCarrier).filter(isPaidDeliveryOption) }));
      }
    } catch (e) {
      atyabLog("storeInfo FAIL", key);
      dispatch(storeInfoActions.loadFailed({ key: key, error: (e && e.message) || "تعذّر جلب البيانات" }));
    }
  };
}
