import { createProductsSlice } from "./productsFactory.js";
import { ENDPOINTS, mockGetAllIncenses } from "../api.js";

/* ============================================================
   أطياب الجاسم — شريحة البخور (بخور فقط)
   نفس نمط شريحة العطور تماماً: { list, status, error } +
   getAllIncenses للقراءة فقط بشرط عدم التكرار والقائمة ممتلئة.
   ============================================================ */

const base = createProductsSlice({
  sliceName: "incenses",
  kind: "incense",
  kindGroup: "bakhoor",
  kindLabelAr: "بخور",
  kindLabelEn: "Bakhoor",
  searchType: "bakhoor",
  endpoint: ENDPOINTS.getAllIncenses,
  mockFn: mockGetAllIncenses
});

export const getAllIncenses = base.getAll;
export const refreshIncensesStock = base.refreshStock;
export const selectIncensesList = base.selectList;
export const selectIncensesStatus = base.selectStatus;
export const selectIncensesError = base.selectError;
export const selectIncenseById = base.selectById;

export default base.reducer;
